const raw = $input.first().json;
const ts = raw.timestamp || new Date().toISOString();
const deviceId = raw.device_id || raw.deviceId || 'unknown';
const zone = raw.zone || raw.zona || 'A';

const data = {
  timestamp: ts,
  device_id: deviceId,
  zone: zone,
  ph: parseFloat(raw.ph ?? raw.pH ?? null),
  ec: parseFloat(raw.ec ?? raw.EC ?? null),
  temp_agua: parseFloat(raw.temp_agua ?? raw.water_temp ?? null),
  temp_aire: parseFloat(raw.temp_aire ?? raw.air_temp ?? null),
  humedad: parseFloat(raw.humedad ?? raw.humidity ?? null),
  co2: parseFloat(raw.co2 ?? raw.CO2 ?? null),
  luz_par: parseFloat(raw.luz_par ?? raw.par ?? null),
  o2_disuelto: parseFloat(raw.o2_disuelto ?? raw.dissolved_o2 ?? null),
  raw_payload: JSON.stringify(raw)
};

return [{ json: data }];

const d = $input.first().json;
const errors = [];

if (!d.device_id || d.device_id === 'unknown') errors.push('device_id requerido');
if (isNaN(d.ph) && isNaN(d.ec) && isNaN(d.temp_agua)) errors.push('Al menos un sensor numérico requerido');
if (d.ph !== null && !isNaN(d.ph) && (d.ph < 0 || d.ph > 14)) errors.push(`pH fuera de rango: ${d.ph}`);
if (d.ec !== null && !isNaN(d.ec) && (d.ec < 0 || d.ec > 10)) errors.push(`EC fuera de rango: ${d.ec}`);

if (errors.length > 0) {
  throw new Error('Validación fallida: ' + errors.join(', '));
}

return [{ json: { ...d, validado: true } }];

const d = $input.first().json;
const alertas = [];

const rangos = {
  ph:         { min: 5.5, max: 6.5,  unidad: '' },
  ec:         { min: 1.2, max: 3.5,  unidad: ' mS/cm' },
  temp_agua:  { min: 16,  max: 24,   unidad: '°C' },
  temp_aire:  { min: 15,  max: 32,   unidad: '°C' },
  humedad:    { min: 40,  max: 80,   unidad: '%' },
  co2:        { min: 400, max: 1200, unidad: ' ppm' },
  o2_disuelto:{ min: 6,   max: 14,   unidad: ' mg/L' }
};

for (const [param, rango] of Object.entries(rangos)) {
  const val = d[param];
  if (val === null || isNaN(val)) continue;
  if (val < rango.min || val > rango.max) {
    alertas.push({
      parametro: param,
      valor: val,
      min: rango.min,
      max: rango.max,
      unidad: rango.unidad,
      device_id: d.device_id,
      zone: d.zone,
      timestamp: d.timestamp
    });
  }
}

return [{ json: { ...d, alertas, tiene_alertas: alertas.length > 0 } }];

const d = $input.first().json;
const crypto = require('crypto');
const payload = JSON.stringify({ device: d.device_id, ts: d.timestamp, data: d });
const hash = crypto.createHash('sha256').update(payload).digest('hex');
return [{ json: { ...d, trazabilidad_hash: hash } }];

const d = $input.first().json;
const crypto = require('crypto');
const key = Buffer.from(process.env.AES_KEY_HEX || '0'.repeat(64), 'hex');
const iv = crypto.randomBytes(16);
const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
let encrypted = cipher.update(JSON.stringify(d), 'utf8', 'hex');
encrypted += cipher.final('hex');
const authTag = cipher.getAuthTag().toString('hex');
return [{ json: {
  cifrado: encrypted,
  iv: iv.toString('hex'),
  auth_tag: authTag,
  device_id: d.device_id,
  timestamp: d.timestamp
}}];

const items = $input.all();
const alertas = [];

const rangos = {
  ph:         { min: 5.5, max: 6.5,  critico_min: 5.0, critico_max: 7.0 },
  ec:         { min: 1.2, max: 3.5,  critico_min: 0.8, critico_max: 4.5 },
  temp_agua:  { min: 16,  max: 24,   critico_min: 12,  critico_max: 28 },
  temp_aire:  { min: 15,  max: 32,   critico_min: 10,  critico_max: 38 },
  o2_disuelto:{ min: 6,   max: 14,   critico_min: 4,   critico_max: 14 }
};

for (const item of items) {
  const d = item.json;
  for (const [param, rango] of Object.entries(rangos)) {
    const val = parseFloat(d[param]);
    if (isNaN(val)) continue;
    if (val < rango.critico_min || val > rango.critico_max) {
      alertas.push({ ...d, parametro: param, valor: val, nivel: 'critica', rango });
    } else if (val < rango.min || val > rango.max) {
      alertas.push({ ...d, parametro: param, valor: val, nivel: 'media', rango });
    }
  }
}

return alertas.map(a => ({ json: a }));

const d = $input.first().json;
let prioridad = 0;
if (d.nivel === 'critica') prioridad = 10;
else if (d.nivel === 'media') prioridad = 5;
else prioridad = 1;
const desviacion = Math.abs(d.valor - ((d.rango.min + d.rango.max) / 2));
prioridad += desviacion;
return [{ json: { ...d, prioridad: Math.round(prioridad * 100) / 100 } }];

const items = $input.all();
const evaluaciones = items.map(item => {
  const d = item.json;
  const kpis = {
    eficiencia_nutricional: (() => {
      if (isNaN(d.avg_ec) || isNaN(d.avg_ph)) return null;
      const ec_ok = d.avg_ec >= 1.5 && d.avg_ec <= 3.0;
      const ph_ok = d.avg_ph >= 5.5 && d.avg_ph <= 6.5;
      return ec_ok && ph_ok ? 'ÓPTIMO' : 'SUBÓPTIMO';
    })(),
    confort_termico: (() => {
      const t = d.avg_temp_aire;
      if (isNaN(t)) return null;
      return t >= 18 && t <= 28 ? 'ÓPTIMO' : t >= 15 && t <= 32 ? 'ACEPTABLE' : 'CRÍTICO';
    })(),
    humedad_relativa: (() => {
      const h = d.avg_humedad;
      if (isNaN(h)) return null;
      return h >= 50 && h <= 75 ? 'ÓPTIMO' : 'FUERA_RANGO';
    })(),
    co2_enriquecimiento: (() => {
      const c = d.avg_co2;
      if (isNaN(c)) return null;
      return c >= 600 && c <= 1000 ? 'ÓPTIMO' : c > 1000 ? 'EXCESO' : 'DEFICIENTE';
    })()
  };
  return { json: { device_id: d.device_id, zone: d.zone, kpis, datos: d, evaluado_en: new Date().toISOString() } };
});
return evaluaciones;

const items = $input.all();
const metricas = {
  timestamp: new Date().toISOString(),
  total_dispositivos: new Set(items.map(i => i.json.device_id)).size,
  zonas_activas: new Set(items.map(i => i.json.zone)).size,
  kpi_resumen: {
    eficiencia_nutricional_optimo: items.filter(i => i.json.kpis.eficiencia_nutricional === 'ÓPTIMO').length,
    confort_termico_optimo: items.filter(i => i.json.kpis.confort_termico === 'ÓPTIMO').length,
    alertas_criticas_hora: 0
  },
  evaluaciones: items.map(i => i.json)
};
return [{ json: metricas }];

const d = $input.first().json;
const optimos = d.evaluaciones.filter(e => Object.values(e.kpis).every(v => v === 'ÓPTIMO' || v === null)).length;
const total = d.evaluaciones.length;
const pct = total > 0 ? Math.round(optimos / total * 100) : 0;
const msg = `📊 *Resumen CTAEX* — ${new Date().toLocaleString('es-ES')}

✅ Dispositivos en rango óptimo: ${optimos}/${total} (${pct}%)
🌡️ Zonas activas: ${d.zonas_activas}
📡 Total dispositivos: ${d.total_dispositivos}

${pct >= 80 ? '🟢 Estado general: ÓPTIMO' : pct >= 50 ? '🟡 Estado general: ACEPTABLE' : '🔴 Estado general: REQUIERE ATENCIÓN'}`;
return [{ json: { mensaje: msg, pct_optimo: pct, datos: d } }];

const metricas = $('Get Metrics').all().map(i => i.json);
const sensores = $('Get Sensor Data').all().map(i => i.json);
const alertas = $('Get Alerts').all().map(i => i.json);
return [{ json: { metricas, sensores, alertas } }];

const d = $input.first().json;
const ultima = d.sensores.length > 0 ? d.sensores[0] : {};
const alertas_criticas = d.alertas.filter(a => a.nivel === 'critica').length;
const alertas_medias = d.alertas.filter(a => a.nivel === 'media').length;
const estado = alertas_criticas > 0 ? 'CRÍTICO' : alertas_medias > 5 ? 'ALERTA' : 'NORMAL';
return [{ json: {
  estado,
  ultima_lectura: ultima,
  alertas_criticas,
  alertas_medias,
  metricas_24h: d.metricas,
  total_registros_hora: d.sensores.length,
  timestamp: new Date().toISOString()
}}];
